def toHexspeak(num: str) -> str:
    # Convert decimal string to int, then to hexadecimal (without '0x' prefix), uppercase
    hex_str = hex(int(num))[2:].upper()
    mapping = {'0': 'O', '1': 'I',
               'A': 'A', 'B': 'B', 'C': 'C', 'D': 'D', 'E': 'E', 'F': 'F'}
    result = []
    for c in hex_str:
        if c in mapping:
            result.append(mapping[c])
        else:
            # Forbidden digits '2'-'9'
            return "ERROR"
    return ''.join(result)
